import React, { useState } from 'react';

export default function RestaurantBooking() {
  const [formData, setFormData] = useState({
    location: '',
    cuisine: '',
    date: '',
    time: '',
    partySize: ''
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      // محاكاة استدعاء API باستخدام axios
      // const response = await axios.post('/api/search-tables', formData);
      
      // محاكاة تأخير الشبكة
      await new Promise(resolve => setTimeout(resolve, 1500));
      
      console.log('البحث عن:', formData);
      setMessage('تم العثور على طاولات متاحة! سيتم توجيهك لصفحة النتائج...');
      
      // هنا يمكن إضافة منطق التوجيه لصفحة النتائج
      // window.location.href = '/search-results';
      
    } catch (error) {
      console.error('خطأ في البحث:', error);
      setMessage('حدث خطأ أثناء البحث. يرجى المحاولة مرة أخرى.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      {/* Bootstrap CSS CDN */}
      <link 
        href="https://cdnjs.cloudflare.com/ajax/libs/bootstrap/5.3.0/css/bootstrap.min.css" 
        rel="stylesheet" 
      />
      
      {/* Custom CSS */}
      <link rel="stylesheet" href="./restaurant-booking.css" />
      
      <div className="position-relative min-vh-100 overflow-hidden">

        {/* Background */}
        <div className="restaurant-bg position-absolute w-100 h-100"></div>

        {/* Animated bokeh lights */}
        {[...Array(8)].map((_, i) => (
          <div
            key={i}
            className="bokeh-light"
            style={{
              width: Math.random() * 25 + 10 + 'px',
              height: Math.random() * 25 + 10 + 'px',
              left: Math.random() * 100 + '%',
              top: Math.random() * 100 + '%',
              animationDelay: Math.random() * 2 + 's',
              animationDuration: (Math.random() * 2 + 2) + 's'
            }}
          />
        ))}

        {/* Wine glasses decoration */}
        <div className="position-absolute bottom-0 start-0 w-100" style={{height: '120px'}}>
          <div className="d-flex justify-content-around align-items-end h-100 px-5">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="wine-glass" style={{animationDelay: i * 0.5 + 's'}}></div>
            ))}
          </div>
        </div>

        {/* Main Content */}
        <div className="position-relative d-flex flex-column align-items-center justify-content-center min-vh-100 px-3" style={{zIndex: 10}}>
          
          {/* Title */}
          <div className="text-center mb-5">
            <h1 className="display-1 fw-bold text-white title-glow mb-4" style={{letterSpacing: '3px'}}>
              BOOK A TABLE
            </h1>
            <div className="mx-auto bg-warning" style={{width: '120px', height: '2px', opacity: 0.8}}></div>
          </div>

          {/* Booking Form */}
          <div className="glass-form rounded-4 p-4 p-md-5" style={{maxWidth: '900px', width: '100%'}}>
            {message && (
              <div className={`alert ${message.includes('خطأ') ? 'alert-danger' : 'alert-success'} mb-4`} role="alert">
                {message}
              </div>
            )}
            
            <form onSubmit={handleSearch}>
              <div className="row g-4">
                {/* Location */}
                <div className="col-md-4">
                  <label htmlFor="location" className="form-label text-white fw-semibold">
                    Location:
                  </label>
                  <input
                    type="text"
                    className="form-control form-control-lg form-control-glass"
                    id="location"
                    name="location"
                    value={formData.location}
                    onChange={handleInputChange}
                    placeholder="اختر الموقع"
                    required
                  />
                </div>
                
                {/* Cuisine */}
                <div className="col-md-4">
                  <label htmlFor="cuisine" className="form-label text-white fw-semibold">
                    Cuisine:
                  </label>
                  <input
                    type="text"
                    className="form-control form-control-lg form-control-glass"
                    id="cuisine"
                    name="cuisine"
                    value={formData.cuisine}
                    onChange={handleInputChange}
                    placeholder="أدخل نوع المطبخ"
                    required
                  />
                </div>

                {/* Date */}
                <div className="col-md-4">
                  <label htmlFor="date" className="form-label text-white fw-semibold">
                    Date:
                  </label>
                  <input
                    type="date"
                    className="form-control form-control-lg form-control-glass"
                    id="date"
                    name="date"
                    value={formData.date}
                    onChange={handleInputChange}
                    min={new Date().toISOString().split('T')[0]}
                    required
                  />
                </div>

                {/* Time */}
                <div className="col-md-4">
                  <label htmlFor="time" className="form-label text-white fw-semibold">
                    Time:
                  </label>
                  <input
                    type="time"
                    className="form-control form-control-lg form-control-glass"
                    id="time"
                    name="time"
                    value={formData.time}
                    onChange={handleInputChange}
                    required
                  />
                </div>

                {/* Party Size */}
                <div className="col-md-4">
                  <label htmlFor="partySize" className="form-label text-white fw-semibold">
                    Party Size:
                  </label>
                  <input
                    type="number"
                    className="form-control form-control-lg form-control-glass"
                    id="partySize"
                    name="partySize"
                    value={formData.partySize}
                    onChange={handleInputChange}
                    placeholder="عدد الأشخاص"
                    min="1"
                    max="20"
                    required
                  />
                </div>

                {/* Search Button */}
                <div className="col-md-4 d-flex align-items-end">
                  <button
                    type="submit"
                    className="btn btn-search btn-lg w-100 py-3"
                    disabled={loading}
                  >
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                        Searching...
                      </>
                    ) : (
                      'SEARCH'
                    )}
                  </button>
                </div>
              </div>
            </form>
          </div>

          {/* Decorative Elements */}
          <div className="position-absolute" style={{top: '80px', left: '40px', width: '20px', height: '20px', border: '2px solid #ffc107', transform: 'rotate(45deg)', opacity: 0.3}}></div>
          <div className="position-absolute rounded-circle" style={{top: '160px', right: '80px', width: '15px', height: '15px', backgroundColor: '#ffc107', opacity: 0.4}}></div>
          <div className="position-absolute rounded-circle" style={{bottom: '120px', left: '80px', width: '25px', height: '25px', border: '2px solid #fd7e14', opacity: 0.3}}></div>
          <div className="position-absolute" style={{bottom: '80px', right: '40px', width: '18px', height: '18px', backgroundColor: '#fd7e14', transform: 'rotate(45deg)', opacity: 0.4}}></div>
        </div>
      </div>

      {/* Bootstrap JS CDN */}
      <script src="https://cdnjs.cloudflare.com/ajax/libs/bootstrap/5.3.0/js/bootstrap.bundle.min.js"></script>
    </>
  );
}
